'use strict';
const $=id=>document.getElementById(id);
const stages=[
 {key:'html',name:'Layout',title:'Make room for real work.',description:'Build the form, list, and controls your app needs. IDs connect these elements to JavaScript.',task:'Customize the app heading and one form label. Keep the IDs so the app can still find its controls.',location:'index.html · body',hint:'Put this inside <body>. The other recipes connect to these elements.',explanation:'<p><code>&lt;form&gt;</code> collects input. <code>required</code> prevents an empty submission.</p><p><code>id</code> gives JavaScript a stable address. Change visible words freely; update selectors if you rename IDs.</p>',takeaway:'A useful app starts with a clear action.',summary:'The form lets someone enter information; the list gives them a place to see the result.'},
 {key:'css',name:'Design',title:'Make the important parts clear.',description:'Use spacing, contrast, and color to make your form and records easy to read.',task:'Change --accent to #176b62. Then change the article border-radius from 10px to 4px.',location:'index.html · style',hint:'Put this inside <style> in <head>. CSS changes presentation, not your records.',explanation:'<p><code>--accent</code> is a reusable color. <code>var(--accent)</code> reads it.</p><p><code>display: grid</code> arranges the form. <code>gap</code> separates its fields.</p>',takeaway:'Design supports the task.',summary:'A clear form and readable records matter more than decorative sections.'},
 {key:'logic',name:'Actions',title:'Turn input into something useful.',description:'Read the form, update records, and render them on screen. This is the working heart of your app.',task:'',location:'index.html · script',hint:'Put this after the saving functions and after your HTML, before </body>.',explanation:'<p><code>records</code> holds your items. <code>render()</code> turns them into visible cards.</p><p><code>preventDefault()</code> stops the form from reloading the page.</p><p><code>textContent</code> displays user text without interpreting it as HTML.</p>',takeaway:'The whole loop is connected.',summary:'Input becomes a record, and the record becomes something you can see and act on.'},
 {key:'storage',name:'Saving',title:'Keep your work between visits.',description:'Save records in the current browser. There is no account, cloud sync, or server database.',task:'Inspect STORE_KEY: each app uses its own key. Download and open your app, add a record, then reload to check saving.',location:'index.html · script · before actions',hint:'Saving functions run before the actions recipe. The isolated preview cannot access browser storage.',explanation:'<p><code>JSON.stringify</code> turns records into text. <code>JSON.parse</code> reads them back.</p><p><code>localStorage</code> keeps them in this browser. Clearing browser data removes them.</p><p><code>try/catch</code> lets the app stay usable when storage is unavailable.</p>',takeaway:'Saving has a boundary.',summary:'Your exported app saves locally when the browser permits it. The preview uses sample records and resets when Run is pressed.'},
 {key:'extras',name:'Extras',title:'Give your app a useful extra.',description:'Add an operation that helps someone find, review, or export their records.',task:'',location:'index.html · script · after actions',hint:'Put this after the actions recipe. It reuses existing records and the render function.',explanation:'<p>Filters change what you see without removing records.</p><p>The finance recipe exports the currently selected month. CSV text is quoted and spreadsheet formulas are neutralized.</p>',takeaway:'Ready to use, ready to change.',summary:'Download one complete HTML file containing your layout, design, actions, saving, and extras.'}
];
let selected=0,current=0;
const drafts=RECIPES.map(r=>Object.fromEntries(stages.map(s=>[s.key,r[s.key]])));
let generation=0;
function saveEditor(){drafts[selected][stages[current].key]=$('editor').value;}
function compose(code,isolated=false){
 const csp=isolated?`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; connect-src 'none'; form-action 'none'; base-uri 'none'">`:'';
 const script=[code.storage,code.logic,code.extras].join('\n;\n').replace(/<\/script/gi,'<\\/script');
 const report=isolated?`<script>window.addEventListener('error',function(e){parent.postMessage({type:'recipe-error',generation:${generation},message:e.message},'*')});<\/script>`:'';
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${RECIPES[selected].title}</title>${csp}<style>${code.css}</style></head><body>${code.html}${report}<script>${script}<\/script></body></html>`;
}
function preview(){generation++;$('frame').srcdoc=compose(drafts[selected],true);}
function showStep(index){if(!Number.isInteger(index)||index<0||index>=stages.length)throw new Error('Choose a step from 0 to 4.');current=index;const s=stages[index],r=RECIPES[selected];$('editor').value=drafts[selected][s.key];$('step-label').textContent=`0${index+1} / ${s.name.toUpperCase()}`;$('file-name').textContent=s.location;$('lesson-title').textContent=s.title;$('lesson-description').textContent=s.description;$('task-text').textContent=index===2?r.task:index===4?(r.id==='finance'?'Export the selected month as CSV. Try changing the column labels in the first row.':'Add a record, then try each filter. Change the filter labels in the layout recipe.'):s.task;$('editor-label').textContent=s.key==='html'?'HTML':s.key==='css'?'CSS':'JAVASCRIPT';$('editor-help').textContent=s.hint;$('explanation').innerHTML=s.explanation;$('takeaway-title').textContent=s.takeaway;$('takeaway-text').textContent=s.summary;$('feedback').textContent='';$('next').textContent=index===4?'Download app':'Next recipe';document.querySelectorAll('[data-step]').forEach((b,i)=>{b.classList.toggle('selected',i===index);if(i===index)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});}
function chooseRecipe(index){saveEditor();selected=index;$('deploy-app-name').textContent=RECIPES[index].title;showStep(0);document.querySelectorAll('[data-recipe]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));$('preview-state').textContent=RECIPES[index].title+' · sample data';preview();}
function run(){saveEditor();const code=drafts[selected],s=stages[current];let warning='';if(!code[s.key].trim())warning='This snippet is empty. Add code or reset the example.';try{new Function([code.storage,code.logic,code.extras].join('\n;\n'));}catch(e){warning='Check your JavaScript: '+e.message;}$('feedback').textContent=warning||'Preview updated. Try adding a record and using the controls.';if(!warning)preview();return {recipe:RECIPES[selected].id,step:current,updated:!warning,warning};}
function download(){saveEditor();const url=URL.createObjectURL(new Blob([compose(drafts[selected])],{type:'text/html'}));const a=document.createElement('a');a.href=url;a.download=RECIPES[selected].id+'-app.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('feedback').textContent='Downloaded '+a.download+'. Open it in a browser and try adding a record.';}
RECIPES.forEach((r,i)=>{const b=document.createElement('button');b.dataset.recipe=i;b.className='recipe-card';b.setAttribute('aria-pressed',String(i===0));const label=document.createElement('span');label.className='eyebrow';label.textContent=r.tag;const title=document.createElement('strong');title.textContent=r.title;const desc=document.createElement('p');desc.textContent=r.description;const level=document.createElement('small');level.textContent=r.difficulty+' · 5 recipes';b.append(label,title,desc,level);b.onclick=()=>chooseRecipe(i);$('catalog').append(b);});
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{saveEditor();showStep(Number(b.dataset.step));});$('run').onclick=run;$('download').onclick=download;$('next').onclick=()=>{saveEditor();current===4?download():showStep(current+1);};$('reset').onclick=()=>{$('editor').value=RECIPES[selected][stages[current].key];run();};$('editor').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)){e.preventDefault();run();}});for(const size of ['desktop','mobile'])$(size).onclick=()=>{$('frame-wrap').style.width=size==='mobile'?'min(100%, 360px)':'100%';$('desktop').setAttribute('aria-pressed',String(size==='desktop'));$('mobile').setAttribute('aria-pressed',String(size==='mobile'));};
window.addEventListener('message',e=>{if(e.source!==$('frame').contentWindow||e.data?.type!=='recipe-error'||e.data.generation!==generation||typeof e.data.message!=='string')return;$('feedback').textContent='Preview error: '+e.data.message.slice(0,250);});
$('deploy-download').onclick=download;
$('download-config').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({framework:null,buildCommand:'',outputDirectory:'.'},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='vercel.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('deploy-app-name').textContent=RECIPES[selected].title;
showStep(0);preview();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'set_recipe_code',description:'Choose an app, edit a recipe step, and run its code in the visible workspace.',inputSchema:{type:'object',properties:{recipe:{type:'integer',minimum:0,maximum:2},step:{type:'integer',minimum:0,maximum:4},code:{type:'string',maxLength:50000}},required:['recipe','step','code'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||!Number.isInteger(input.recipe)||input.recipe<0||input.recipe>2||!Number.isInteger(input.step)||input.step<0||input.step>4||typeof input.code!=='string'||input.code.length>50000)throw new Error('Use recipe 0–2, step 0–4, and code under 50,000 characters.');chooseRecipe(input.recipe);showStep(input.step);$('editor').value=input.code;return run();}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
